#!/usr/bin/env pwsh
$basedir=Split-Path $MyInvocation.MyCommand.Definition -Parent

$exe=""
$pathsep=":"
$env_node_path=$env:NODE_PATH
$new_node_path="D:\Posoroko\TimberFrameStudio\node_modules\.pnpm\nuxt@4.6.2_561bb04acc03cd472e8e40700b031951\node_modules\nuxt\node_modules;D:\Posoroko\TimberFrameStudio\node_modules\.pnpm\nuxt@4.6.2_561bb04acc03cd472e8e40700b031951\node_modules;D:\Posoroko\TimberFrameStudio\node_modules\.pnpm\node_modules"
if ($PSVersionTable.PSVersion -lt "6.0" -or $IsWindows) {
  # Fix case when both the Windows and Linux builds of Node
  # are installed in the same directory
  $exe=".exe"
  $pathsep=";"
} else {
  $new_node_path="/mnt/d/Posoroko/TimberFrameStudio/node_modules/.pnpm/nuxt@4.6.2_561bb04acc03cd472e8e40700b031951/node_modules/nuxt/node_modules:/mnt/d/Posoroko/TimberFrameStudio/node_modules/.pnpm/nuxt@4.6.2_561bb04acc03cd472e8e40700b031951/node_modules:/mnt/d/Posoroko/TimberFrameStudio/node_modules/.pnpm/node_modules"
}
if ([string]::IsNullOrEmpty($env_node_path)) {
  $env:NODE_PATH=$new_node_path
} else {
  $env:NODE_PATH="$new_node_path$pathsep$env_node_path"
}
$ret=0
if (Test-Path "$basedir/node$exe") {
  # Support pipeline input
  if ($MyInvocation.ExpectingInput) {
    $input | & "$basedir/node$exe"  "$basedir/../nuxt/bin/nuxt.mjs" $args
  } else {
    & "$basedir/node$exe"  "$basedir/../nuxt/bin/nuxt.mjs" $args
  }
  $ret=$LASTEXITCODE
} else {
  # Support pipeline input
  if ($MyInvocation.ExpectingInput) {
    $input | & "node$exe"  "$basedir/../nuxt/bin/nuxt.mjs" $args
  } else {
    & "node$exe"  "$basedir/../nuxt/bin/nuxt.mjs" $args
  }
  $ret=$LASTEXITCODE
}
$env:NODE_PATH=$env_node_path
exit $ret
